import itertools

def solve_for_n(n, k):
    configs = list(itertools.combinations(range(2 * n), n))

    def get_state(comb):
        s = ['C'] * (2 * n)
        for i in comb:
            s[i] = 'A'
        return "".join(s)

    def op(s, k):
        # k is 1-indexed
        idx = k - 1
        char = s[idx]
        # Find boundaries of the block
        left = idx
        while left > 0 and s[left - 1] == char:
            left -= 1
        right = idx
        while right < len(s) - 1 and s[right + 1] == char:
            right += 1

        block = s[left:right + 1]
        remaining = s[:left] + s[right + 1:]
        return "".join(block) + remaining

    def count_boundaries(s):
        count = 0
        for i in range(len(s) - 1):
            if s[i] != s[i+1]:
                count += 1
        return count

    for comb in configs:
        s = get_state(comb)
        seen = {s}
        while count_boundaries(s) > 1:
            s = op(s, k)
            if s in seen:
                return False # Cycle
            seen.add(s)
    return True

def find_a_b(n):
    works = []
    for k in range(1, 2 * n + 1):
        if solve_for_n(n, k):
            works.append(k)
    return works

for n in range(1, 6):
    print(f"n={n}, works={find_a_b(n)}")

